function validate(config,defaults,schema){
  if(!config||typeof config!=='object'||Array.isArray(config))throw new Error('Die Kartenkonfiguration muss ein Objekt sein.');
  Object.keys(config).forEach(function(k){
    if(/^cover_(?:[5-9]|[1-9][0-9]+)_(?:entity|battery_entity|name)$/.test(k))throw new Error('Maximal 4 Rollos pro Raum sind zulässig.');
  });
  var c=copy(defaults,config);
  schema.forEach(function(g){g.fields.forEach(function(f){var v=c[f.key];if(f.kind==='number'){if(v===''||v==null)c[f.key]=defaults[f.key];else{var n=num(v);if(n===null||(f.min!=null&&n<f.min)||(f.max!=null&&n>f.max))throw new Error(f.label+': ungültiger Wert.');c[f.key]=n;}}
    else if(f.kind==='check'){if(typeof v!=='boolean')throw new Error(f.label+': true oder false erforderlich.');}
    else if(v!=null&&typeof v!=='string')throw new Error(f.label+': Text erforderlich.');
    if(f.domains&&c[f.key]&&f.domains.indexOf(domain(c[f.key]))===-1)throw new Error(f.label+': unzulässige Entitätsdomain.');
    if(f.domains&&c[f.key]&&!/^[a-z0-9_]+\.[a-z0-9_]+$/.test(c[f.key]))throw new Error(f.label+': ungültige Entitäts-ID.');
    if(f.options&&f.options.indexOf(c[f.key])===-1)throw new Error(f.label+': ungültige Auswahl.');
  });});
  if(num(c.min_temp)!==null&&num(c.max_temp)!==null&&c.min_temp>c.max_temp)throw new Error('Min. Temperatur muss kleiner oder gleich Max. Temperatur sein.');return c;
}
