function entity(label,key,domains,device){return field(label,key,'entity',{domains:domains,device:device});}
function weatherFields(room){return [field('Wetter anzeigen','weather_enabled','check')].filter(function(){return room;}).concat([
  entity('HA Wetter / Open-Meteo-Sensor','weather_entity',['weather','sensor'],'weather'),entity('Außentemperatur (optional)',room?'outside_temperature_entity':'temperature_entity',['sensor'],'temperature'),entity('Außenfeuchte (optional)',room?'outside_humidity_entity':'humidity_entity',['sensor'],'humidity'),entity('Sonnenstatus (optional)','sun_entity',['sun']),field('Wettermodell',room?'weather_model':'forecast_model','select',{options:['best_match','geosphere_seamless']}),field('Aktualisierung in Minuten',room?'weather_refresh_minutes':'refresh_minutes','number',{min:5,max:1440}),field('Ort / Standort',room?'weather_source':'source_label')]);}
