function register(Card,name,description){
  if(!window.customElements||!HTMLElement.prototype.attachShadow){console.error('Frankys_Stuff Room Card v0.3.0 requires Custom Elements v1 and Shadow DOM.');return;}
  if(!customElements.get(TAG))customElements.define(TAG,Card);
  if(!customElements.get(TAG+'-editor'))customElements.define(TAG+'-editor',StableEditor);
  window.customCards=window.customCards||[];
  if(!window.customCards.some(function(x){return x.type===TAG;}))window.customCards.push({type:TAG,name:name,description:description,preview:true});
}

